package career.assistant.application.service;
import career.assistant.application.ats.PublicAtsAdapters; import career.assistant.application.entity.*; import career.assistant.application.repository.ApplicationRepository; import career.assistant.company.repository.CompanyRepository; import career.assistant.document.dto.ResumeDetailsResponse; import career.assistant.document.entity.ResumeVersion; import career.assistant.document.service.*; import career.assistant.job.entity.Job; import career.assistant.job.service.JobService; import career.assistant.jobscore.entity.JobScore; import career.assistant.jobscore.service.JobScoringService; import org.junit.jupiter.api.*; import java.math.BigDecimal; import java.util.*; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.Mockito.*;
class ApplicationWorkflowServiceTest {ApplicationRepository apps=mock(ApplicationRepository.class);JobService jobs=mock(JobService.class);JobScoringService scoring=mock(JobScoringService.class);ResumeService resumes=mock(ResumeService.class);CoverLetterService letters=mock(CoverLetterService.class);CompanyRepository companies=mock(CompanyRepository.class);ApplicationNotificationService mail=mock(ApplicationNotificationService.class);ApplicationWorkflowService service=new ApplicationWorkflowService(apps,jobs,scoring,resumes,letters,companies,new PublicAtsAdapters(),mail,false,true,3,"boards.greenhouse.io,jobs.lever.co,apply.workable.com");
 @Test void lowConfidenceRequiresConfirmationAndCreatesNoDocuments(){UUID id=UUID.randomUUID();Job j=mock(Job.class);JobScore s=score("LOW",95,100);when(jobs.findRequired(id)).thenReturn(j);when(scoring.findOrScore(j)).thenReturn(s);assertThrows(ResumeConflictException.class,()->service.generate(id,false));verifyNoInteractions(resumes,letters);}
 @Test void duplicatePackageIsReturnedWithoutRegeneration(){UUID jid=UUID.randomUUID(),aid=UUID.randomUUID();Job j=job(jid);Application a=new Application();a.setJob(j);a.setResumeVersionId(UUID.randomUUID());a.setCoverLetterId(UUID.randomUUID());JobScore s=score("HIGH",95,100);when(jobs.findRequired(jid)).thenReturn(j);when(scoring.findOrScore(j)).thenReturn(s);when(apps.findByJobId(jid)).thenReturn(Optional.of(a));service.generate(jid,false);verifyNoInteractions(resumes,letters);}
 @Test void missingRequiredSkillsRoutesReadyApplicationToReview(){UUID jid=UUID.randomUUID();Job j=job(jid);Application a=new Application();a.setJob(j);a.setStatus(ApplicationStatus.READY_TO_APPLY);a.setResumeVersionId(UUID.randomUUID());a.setCoverLetterId(UUID.randomUUID());JobScore s=score("HIGH",95,75);when(apps.findById(any())).thenReturn(Optional.of(a));when(scoring.findOrScore(j)).thenReturn(s);when(resumes.activeMasterEntity()).thenReturn(Optional.of(new ResumeVersion()));when(apps.save(a)).thenReturn(a);var result=service.run(UUID.randomUUID());assertEquals(ApplicationStatus.PENDING_REVIEW,result.status());verify(j).setStatus("PENDING_REVIEW");assertTrue(result.reason().contains("required skills"));}
 @Test void approveAndRejectAreExplicitStatusTransitions(){Job j=job(UUID.randomUUID());Application a=new Application();a.setJob(j);a.setResumeVersionId(UUID.randomUUID());a.setCoverLetterId(UUID.randomUUID());when(apps.findById(any())).thenReturn(Optional.of(a));when(scoring.findOrScore(j)).thenReturn(score("HIGH",95,100));when(apps.save(a)).thenReturn(a);assertEquals(ApplicationStatus.READY_TO_APPLY,service.review(UUID.randomUUID(),true,null).status());assertEquals(ApplicationStatus.REJECTED,service.review(UUID.randomUUID(),false,null).status());}
 private static Job job(UUID id){Job j=mock(Job.class);when(j.getId()).thenReturn(id);when(j.getTitle()).thenReturn("DevOps Engineer");when(j.getCompanyId()).thenReturn(UUID.randomUUID());when(j.getJobUrl()).thenReturn("https://boards.greenhouse.io/acme/jobs/12345");when(j.getLocation()).thenReturn("Dubai, UAE");when(j.getCountry()).thenReturn("UAE");when(j.getExperienceMin()).thenReturn(4);when(j.getExperienceMax()).thenReturn(8);return j;}private static JobScore score(String confidence,int score,int required){JobScore s=new JobScore();s.setScore(BigDecimal.valueOf(score));s.setScoringConfidence(confidence);s.setRequiredSkillsScore(BigDecimal.valueOf(required));s.setMatchedKeywords("AWS, Terraform");s.setMissingKeywords(required==100?"":"Kubernetes");return s;}}
